-- =====================================================
-- HAN-SKIN COMPLETE DATABASE SETUP
-- Run this in Supabase SQL Editor
-- =====================================================

-- =====================================================
-- 1. PRODUCTS TABLE
-- =====================================================
DROP TABLE IF EXISTS products CASCADE;

CREATE TABLE products (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  brand TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  category TEXT NOT NULL,
  price DECIMAL(10,2) NOT NULL,
  original_price DECIMAL(10,2),
  image_url TEXT,
  rating DECIMAL(2,1) DEFAULT 0,
  review_count INTEGER DEFAULT 0,
  skin_types TEXT[] DEFAULT '{}',
  skin_concerns TEXT[] DEFAULT '{}',
  key_ingredients TEXT[] DEFAULT '{}',
  avoid_ingredients TEXT[] DEFAULT '{}',
  ingredient_score INTEGER DEFAULT 0,
  buy_url TEXT,
  store TEXT,
  is_featured BOOLEAN DEFAULT false,
  price_updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Products are viewable by everyone" ON products FOR SELECT USING (true);
CREATE INDEX idx_products_category ON products(category);
CREATE INDEX idx_products_brand ON products(brand);
CREATE INDEX idx_products_skin_types ON products USING GIN(skin_types);
CREATE INDEX idx_products_skin_concerns ON products USING GIN(skin_concerns);
CREATE INDEX idx_products_rating ON products(rating DESC);

-- =====================================================
-- 2. INGREDIENTS TABLE (EWG-based safety scores)
-- =====================================================
DROP TABLE IF EXISTS ingredients CASCADE;

CREATE TABLE ingredients (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  aliases TEXT[] DEFAULT '{}',
  safety_rating TEXT NOT NULL CHECK (safety_rating IN ('good', 'okay', 'caution')),
  safety_score INTEGER NOT NULL CHECK (safety_score >= 1 AND safety_score <= 10),
  category TEXT,
  benefits TEXT[] DEFAULT '{}',
  concerns TEXT[] DEFAULT '{}',
  description TEXT,
  ewg_score INTEGER,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE ingredients ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Ingredients are viewable by everyone" ON ingredients FOR SELECT USING (true);
CREATE INDEX idx_ingredients_name ON ingredients(name);
CREATE INDEX idx_ingredients_safety ON ingredients(safety_rating);

